```javascript
import orders from './orders.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'order_status',
    description: 'Get the status of an order',
    inputSchema: {
      type: 'object',
      properties: {
        order_id: { type: 'string', description: 'The order ID' },
        include_history: { type: 'boolean', description: 'Whether to include order history', default: false }
      },
      required: ['order_id'],
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'order_status') {
    throw new Error('Tool not found');
  }

  // Validate args
  const allowedKeys = ['order_id', 'include_history'];
  const keys = Object.keys(args);
  for (const key of keys) {
    if (!allowedKeys.includes(key)) {
      throw new Error(`Unknown field: ${key}`);
    }
  }

  const { order_id, include_history } = args;

  if (typeof order_id !== 'string') {
    throw new Error('order_id must be a string');
  }

  if (include_history !== undefined && typeof include_history !== 'boolean') {
    throw new Error('include_history must be a boolean');
  }

  const order = orders[order_id];
  if (!order) {
    throw new Error(`Order not found: ${order_id}`);
  }

  let result = `Status: ${order.status}`;

  if (include_history) {
    result += ` | History: ${order.history.join(' -> ')}`;
  }

  return {
    content: [{ type: 'text', text: result }]
  };
}
```

